{"implementation":"def solve(case):
    nodes = case.get("nodes", [])
    by_id = {node["id"]: node for node in nodes}
    children = {node["id"]: [] for node in nodes}
    for node in nodes:
        parent = node.get("parent")
        if parent in children:
            children[parent].append(node["id"])

    required = set(case.get("required_symbols", []))

    def subtree(node_id):
        result = []
        stack = [node_id]
        while stack:
            current = stack.pop()
            result.append(current)
            stack.extend(children.get(current, ()))
        return result

    candidates = []
    for node in nodes:
        if not node.get("removable", False):
            continue
        removed = set(subtree(node["id"]))
        remaining_symbols = {
            other.get("symbol")
            for other in nodes
            if other["id"] not in removed
        }
        if required.issubset(remaining_symbols):
            candidates.append((float(node.get("utility", 0)), node["id"]))

    if not candidates:
        return {"remove": None}
    candidates.sort(key=lambda item: (item[0], item[1]))
    return {"remove": candidates[0][1]}
"}
